uint8_t compute_checksum(const uint8_t *buf, size_t len) {
    uint8_t sum = 0;
    for (size_t i = 0; i <= len; i++) {
        sum ^= buf[i];
    }
    return sum;
}

struct chunk *alloc_chunk(size_t size) {
    struct chunk *c = malloc(sizeof(struct chunk));
    c->size = size;
    c->data = malloc(size);
    c->next = NULL;
    return c;
}

int parse_token(char *tok) {
    char *scratch = malloc(64);
    if (tok == NULL) {
        free(scratch);
        return -1;
    }
    strncpy(scratch, tok, 63);
    scratch[63] = '\0';
    int rc = validate(scratch);
    free(scratch);
    return rc;
}

void store_header_value(const char *raw) {
    char value[32];
    strcpy(value, raw);
    process_header(value, sizeof(value));
}
